import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.NRNtD2GE.js";const g=JSON.parse('{"title":"The server holds the catalog as a draft and published versions","description":"","frontmatter":{"status":"accepted","date":"2026-11-10T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0026-the-server-holds-the-catalog-as-a-draft-and-published-versions.md","filePath":"docs/adr/0026-the-server-holds-the-catalog-as-a-draft-and-published-versions.md"}'),r={name:"docs/adr/0026-the-server-holds-the-catalog-as-a-draft-and-published-versions.md"};function i(n,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="the-server-holds-the-catalog-as-a-draft-and-published-versions" tabindex="-1">The server holds the catalog as a draft and published versions <a class="header-anchor" href="#the-server-holds-the-catalog-as-a-draft-and-published-versions" aria-label="Permalink to &quot;The server holds the catalog as a draft and published versions&quot;">​</a></h1><p>Builds on <a href="./0008-curated-catalog-with-stable-slugs">ADR 0008</a> and <a href="./0015-catalog-text-lives-in-translation-files">ADR 0015</a>.</p><p>Until now the catalog changed only by editing <code>catalog/data/exercises.json</code> and the <code>catalog</code> translation files, then shipping a build. The admin now edits it on the server and publishes a new version without a release (<a href="https://github.com/tkint/coach-poulpy/issues/337" target="_blank" rel="noreferrer">#337</a>). The server keeps each exercise on its own in Postgres, as <strong>revisions</strong> (<code>catalog_exercise_revision</code>): the shared <code>Exercise</code> JSON with every text as a map from language to string (ADR 0007), and its place in the catalog and its variation group and rank as columns.</p><ul><li><strong>Published versions</strong> are numbered (<code>catalog_version</code>). A revision records the version that published it (<code>published_in</code>), and version N holds, for each exercise, its latest revision published up to N. A published revision never changes, so neither does a version. The server assembles a version into the document the app bundles (<code>version</code>, <code>exercises</code>, <code>variations</code>) with the same <code>Catalog.toJson</code> as the bundled copy, and keeps the latest one assembled in memory.</li><li><strong>The draft</strong> is the latest version with each exercise&#39;s draft revision in its place: a revision not published yet (<code>published_in</code> null, at most one per exercise). Creating, editing, retiring or offering an exercise again changes its draft revision, or starts one after its latest published revision; a draft that comes back to what the latest version holds is dropped. Nothing reaches a phone yet.</li><li><strong>Publishing</strong> adds the version and marks every draft revision as published in it. Exercises the draft didn&#39;t touch get no new row, so a publish writes only what changed. <code>GET /api/v1/catalog</code> serves the latest, so a phone stores it exactly as it stores its bundled catalog, and no phone-side change is needed (#27 downloads it).</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Slugs never change once published.</strong> A slug is editable in the draft until a version holds the exercise; after that the server refuses the change (<code>409 slug-published</code>). Exercises are retired, never deleted, as ADR 0008 says, and a retired exercise can be offered again.</li><li><strong>Publishing needs every text in every shipped language</strong> (English and French): the name, each instruction and the variation note. The draft may wait for French; only English, the fallback, is needed to save. Publishing with nothing changed is refused too.</li><li><strong>The next version numbers past both the latest published one and the bundled one</strong>, so a phone that came with a newer app build still takes it.</li><li><strong>Variation groups are carried over</strong> in each exercise&#39;s revisions; editing them is not part of the admin yet.</li></ul><h2 id="where-the-catalog-comes-from" tabindex="-1">Where the catalog comes from <a class="header-anchor" href="#where-the-catalog-comes-from" aria-label="Permalink to &quot;Where the catalog comes from&quot;">​</a></h2><ul><li><strong>The first start seeds the database from the bundled catalog</strong>: one revision per exercise, published in the bundled version. Later starts leave the database alone, even when the bundled catalog is newer.</li><li><strong>The database is the source of truth for the published catalog from then on.</strong> The repository&#39;s files stay the source of the <em>bundled</em> catalog, the copy a fresh install starts with offline, and still go through the build of ADR 0015 (text in translation files, merged at build time, checked by CI).</li><li><strong>ADR 0015 still holds for the bundled build, not for the server.</strong> On the server, text lives in each revision next to the structure, since an admin form edits both at once and a published version must hold everything a phone needs. Translators keep proofreading the repository&#39;s files in Fink. Bringing a published version back into those files before a release, so the next build bundles it, is manual for now; a tool for it is a follow-up.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep the repository as the only source, the server serving the build&#39;s copy.</strong> Every catalog fix would still need a release, which is what #26 removes.</li><li><strong>One JSONB document per draft and per version.</strong> Simpler to store and to serve, but every edit would rewrite the whole catalog, two edits could overwrite each other, and no query could reach one exercise.</li><li><strong>A copy of every exercise in every version.</strong> Each version would be one plain query, but every publish would write the whole catalog again to change one exercise. With revisions, a version is rebuilt with one query (each exercise&#39;s latest revision up to it), and storage grows only with what changes.</li><li><strong>Store the text in translation rows on the server, like the files of ADR 0015.</strong> It would keep one shape across the repository and the server, but the published document merges the text back anyway, and the admin form edits an exercise as a whole.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>An exercise added in the admin reaches phones only through the download of #27 until its version is copied back into the repository.</li><li>A fresh install bundles an older catalog than the server&#39;s until then; the download on launch catches it up.</li><li>Editing the repository&#39;s catalog files directly no longer reaches phones that already took a published version with a higher number, so catalog changes go through the admin once the server is live.</li></ul>',12)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
